from collections import deque
G = {'A': ['B', 'C'], 'B': ['A', 'D', 'E'], 'C': ['A', 'F'],
     'D': ['B'], 'E': ['B', 'F'], 'F': ['C', 'E', 'G'], 'G': ['F']}

def bfs(s):
    seen, order, Q = {s}, [], deque([s])
    while Q:
        u = Q.popleft()
        order.append(u)
        for v in G[u]:
            if v not in seen:
                seen.add(v)
                Q.append(v)
    return ''.join(order)

print(bfs('A'), bfs('G'))
