class Node:
    def __init__(self, v, nxt=None):
        self.v, self.nxt = v, nxt

def build(xs):
    head = None
    for x in reversed(xs):
        head = Node(x, head)
    return head

def f(head):
    prev, cur = None, head
    while cur and cur.nxt:
        nxt2 = cur.nxt.nxt
        cur.nxt.nxt = cur
        if prev:
            prev.nxt = cur.nxt
        else:
            head = cur.nxt
        cur.nxt = nxt2
        prev, cur = cur, nxt2
    return head

h = f(build([1, 2, 3, 4, 5]))
out = []
while h:
    out.append(h.v)
    h = h.nxt
